<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/functions.php';
$pdo = getDbConnection(); $error = null;
if (empty($_SESSION['password_reset_user_id']) || empty($_SESSION['password_reset_otp_id']) || ($_SESSION['password_reset_expires'] ?? 0) < time()) { header('Location: ' . baseUrl('forgot-password.php')); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    enforceCsrf(); $input = trim($_POST['otp_code'] ?? '');
    $stmt = $pdo->prepare("SELECT * FROM otp_verifications WHERE otp_id = :oid AND user_id = :uid AND purpose = 'password_reset' AND is_used = 0 LIMIT 1");
    $stmt->execute([':oid' => $_SESSION['password_reset_otp_id'], ':uid' => $_SESSION['password_reset_user_id']]); $row = $stmt->fetch();
    if (!$row || strtotime($row['expires_at']) < time()) $error = 'This OTP is invalid or expired.';
    elseif ((int)$row['attempts'] >= 3 || !preg_match('/^\d{6}$/', $input) || !hash_equals($row['otp_code_hash'], hash('sha256', $input))) {
        if ($row) $pdo->prepare('UPDATE otp_verifications SET attempts = attempts + 1, is_used = IF(attempts + 1 >= 3, 1, is_used) WHERE otp_id = :oid AND purpose = \'password_reset\'')->execute([':oid' => $row['otp_id']]);
        $error = 'This OTP is invalid or expired.';
    } else { $pdo->prepare("UPDATE otp_verifications SET is_used = 1 WHERE otp_id = :oid AND purpose = 'password_reset'")->execute([':oid' => $row['otp_id']]); $_SESSION['password_reset_verified'] = true; header('Location: ' . baseUrl('reset-password.php')); exit; }
}
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Verify OTP - IMD Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= baseUrl('assets/css/imd-auth.css') ?>"></head><body class="bg-light d-flex flex-column min-vh-100"><header class="portal-header"><div class="container"><a href="<?= baseUrl() ?>" class="portal-brand fs-4">IMD Training Division Portal</a><div class="gov-emblem-text">India Meteorological Department | Govt. of India</div></div></header><main class="container my-auto py-5"><div class="row justify-content-center"><div class="col-md-6 col-lg-5"><div class="card card-auth p-4"><div class="card-body"><div class="text-center mb-4"><h3 class="card-title text-imd-navy fw-bold">Verify OTP</h3><p class="text-muted small">Enter the OTP sent to your registered email address.</p></div><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrfField() ?><div class="mb-4"><label for="otp_code" class="form-label text-center d-block fw-bold">OTP</label><input type="text" class="form-control form-control-lg text-center fs-2" id="otp_code" name="otp_code" maxlength="6" pattern="\d{6}" inputmode="numeric" autocomplete="off" required autofocus></div><button type="submit" class="btn btn-imd w-100 py-2 fs-5">Verify OTP</button></form><div class="text-center mt-4"><a href="<?= baseUrl('login.php') ?>" class="text-imd-navy fw-bold text-decoration-none">Back to Login</a></div></div></div></div></div></main><footer class="text-center py-3 mt-auto"><small>&copy; <?= date('Y') ?> India Meteorological Department. Training Division Portal.</small></footer></body></html>
